class ConnectGame:
    # The board is a slanted parallelogram: each row is offset half a cell
    # to the right. In (row, col) coordinates the physically adjacent cells
    # are therefore the four orthogonal neighbours plus the two "legal"
    # diagonals (-1, 1) and (1, -1). The other diagonal is not a valid move.
    _ADJACENT = ((1, 0), (-1, 0), (0, 1), (0, -1), (-1, 1), (1, -1))

    def __init__(self, board):
        self.board = [line.split() for line in board.splitlines() if line.strip()]
        self.winner = self._get_winner()

    def _get_winner(self):
        if self._has_path("O"):
            return "O"
        if self._has_path("X"):
            return "X"
        return ""

    def _has_path(self, player):
        rows = len(self.board)
        cols = len(self.board[0]) if rows else 0
        if player == "O":
            # O plays from top to bottom.
            frontier = {(0, c) for c in range(cols) if self.board[0][c] == "O"}
        else:
            # X plays from left to right.
            frontier = {(r, 0) for r in range(rows) if self.board[r][0] == "X"}
        visited = set(frontier)
        while frontier:
            row, col = frontier.pop()
            if player == "O" and row == rows - 1:
                return True
            if player == "X" and col == cols - 1:
                return True
            for d_row, d_col in self._ADJACENT:
                n_row, n_col = row + d_row, col + d_col
                if (
                    0 <= n_row < rows
                    and 0 <= n_col < cols
                    and (n_row, n_col) not in visited
                    and self.board[n_row][n_col] == player
                ):
                    visited.add((n_row, n_col))
                    frontier.add((n_row, n_col))
        return False

    def get_winner(self):
        return self.winner
